// Shared setup of the G9 differential harness: the recording mock GPU (generated by
// tools/gen_gpu_mock.mjs) installed as `navigator.gpu`, a requestAnimationFrame that never
// fires (so frames do not tick during the asynchronous steps), and the counter alignment
// both sides run before a scenario.
import { createRequire } from 'node:module';
import path from 'node:path';
import { UPSTREAM } from '../../../lib/env.mjs';
const require = createRequire( import.meta.url );
// the mock is generated into diff/core/webgpu (shared with G7 and the shader harness)
const { createMockGPU } = require( '../../webgpu/mock_gpu.cjs' );

export const SRC = path.join( UPSTREAM, 'src' );

export function setup( options = {} ) {

	const mock = createMockGPU( options );
	mock.install( globalThis );
	globalThis.self = globalThis;
	globalThis.requestAnimationFrame = () => 1;
	globalThis.cancelAnimationFrame = () => {};
	return mock;

}

// settle every pending microtask and timer chain
export async function flush() {

	for ( let i = 0; i < 20; i ++ ) await new Promise( ( r ) => setTimeout( r, 0 ) );

}

export const TARGETS = { node: 20000, object3d: 1000, material: 1000, texture: 1000, attribute: 1000, geometry: 1000 };

// mock options of the scenarios that need other adapter features / limits
export const MOCK_OPTIONS = {
	timestamps: { features: [ 'core-features-and-limits', 'timestamp-query' ] },
	compatibility: { features: [] },
	no_adapter: { noAdapter: true },
	features: { features: [ 'core-features-and-limits', 'float32-filterable', 'texture-formats-tier1', 'depth32float-stencil8', 'shader-f16' ] },
	pipeline_errors: { errorScope: ( filter, device ) => ( { type: 'GPUValidationError', message: 'mock validation error' } ), compilationMessages: () => [ { message: 'mock message', type: 'error', lineNum: 3, linePos: 2 }, { message: 'mock warning', type: 'warning', lineNum: 0, linePos: 0 } ] },
};
